import { Component, OnInit, OnDestroy, HostListener } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { Subscription } from 'rxjs';
import { AuthService } from '../services/auth.service';
import { SoportesService } from '../services/soportes.service';
import { SocketService } from '../services/socket.service';
import { Soporte } from '../models/soporte.model';
import { User } from '../models/user.model';

declare const bootstrap: any;

type FiltroEstado = 'todos' | 'pendiente' | 'si' | 'no';

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html',
})
export class DashboardComponent implements OnInit, OnDestroy {
  currentUser: User | null = null;
  soportes: Soporte[] = [];
  loading = false;
  error = '';
  successMsg = '';

  // Filtros
  filtroEstado: FiltroEstado = 'todos';
  searchTerm = '';

  // Nueva solicitud
  nuevaSolicitudForm!: FormGroup;
  savingNew = false;
  imagenPreview: string | null = null;
  nuevaModalVisible = false;

  // Ver imagen ampliada
  imagenViewer: string | null = null;

  // Seguimiento modal
  seguimientoForm!: FormGroup;
  selectedSoporte: Soporte | null = null;
  savingSeguimiento = false;
  seguimientoError = '';

  // Cambiar contraseña
  cambioClaveForm!: FormGroup;
  savingClave = false;
  claveError = '';
  claveSuccess = '';

  // Export excel (admin)
  exportForm!: FormGroup;
  exporting = false;

  // Tiempo real
  wsToast = '';
  private wsSubs: Subscription[] = [];

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private soportesService: SoportesService,
    private socketService: SocketService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.currentUser = this.authService.currentUser;

    this.nuevaSolicitudForm = this.fb.group({
      motivo: ['', [Validators.required, Validators.minLength(5)]],
    });

    this.seguimientoForm = this.fb.group({
      fechaDate: [''],
      fechaTime: [''],
      resolvio: [''],
      observaciones: [''],
    });

    this.cambioClaveForm = this.fb.group({
      password: ['', [Validators.required, Validators.minLength(6)]],
      confirmPassword: ['', [Validators.required, Validators.minLength(6)]],
    });

    this.exportForm = this.fb.group({
      desde: ['', Validators.required],
      hasta: ['', Validators.required],
    });

    this.loadSoportes();
    this.initSocket();
  }

  ngOnDestroy(): void {
    this.wsSubs.forEach(s => s.unsubscribe());
    this.socketService.disconnect();
  }

  // ─── WebSocket ───────────────────────────────────────────────────────────────

  private initSocket(): void {
    const token = this.authService.token;
    if (!token) return;
    this.socketService.connect(token);

    // Nueva solicitud creada por alguien
    this.wsSubs.push(
      this.socketService.on<Soporte>('nuevo-soporte').subscribe(soporte => {
        // Evitar duplicados (el propio usuario admin ya tiene la lista actualizada)
        if (!this.soportes.find(s => s.id === soporte.id)) {
          this.soportes = [soporte, ...this.soportes];
        }
        const area = soporte.usuario?.area || soporte.usuario?.nombre || 'desconocida';
        this.showWsToast(`Nueva solicitud de ${area}`);
      })
    );

    // Solicitud actualizada (seguimiento guardado)
    this.wsSubs.push(
      this.socketService.on<Soporte>('soporte-actualizado').subscribe(soporte => {
        const idx = this.soportes.findIndex(s => s.id === soporte.id);
        if (idx !== -1) {
          this.soportes = [
            ...this.soportes.slice(0, idx),
            soporte,
            ...this.soportes.slice(idx + 1),
          ];
        }
      })
    );

    // Solicitud eliminada
    this.wsSubs.push(
      this.socketService.on<{ id: number }>('soporte-eliminado').subscribe(({ id }) => {
        this.soportes = this.soportes.filter(s => s.id !== id);
      })
    );
  }

  private showWsToast(msg: string): void {
    this.wsToast = msg;
    setTimeout(() => (this.wsToast = ''), 5000);
  }

  // ─── Roles ───────────────────────────────────────────────────────────────────

  get isAdmin(): boolean  { return this.currentUser?.role === 'admin'; }
  get isSoporte(): boolean { return this.currentUser?.role === 'soporte'; }
  get isUser(): boolean   { return this.currentUser?.role === 'user'; }

  // ─── Permisos por fila ───────────────────────────────────────────────────────

  // Edita: admin (cualquier registro) y user (solo los propios)
  canSeguimiento(s: Soporte): boolean {
    if (this.isSoporte) return false;
    if (this.isAdmin) return true;
    return this.isUser && s.usuario?.id === this.currentUser?.id;
  }

  canDelete(s: Soporte): boolean {
    if (this.isSoporte) return false;
    if (this.isAdmin) return true;
    // User: solo pendientes propias
    const tieneMovimiento = !!(s.fechaRespuesta || s.resolvio !== null && s.resolvio !== undefined);
    return !tieneMovimiento && s.usuario?.id === this.currentUser?.id;
  }

  // ─── Filtros ─────────────────────────────────────────────────────────────────

  get filteredSoportes(): Soporte[] {
    let result = [...this.soportes];

    if (this.filtroEstado === 'pendiente') {
      result = result.filter(s => s.resolvio === null || s.resolvio === undefined);
    } else if (this.filtroEstado === 'si') {
      result = result.filter(s => s.resolvio === true);
    } else if (this.filtroEstado === 'no') {
      result = result.filter(s => s.resolvio === false);
    }

    const term = this.searchTerm.trim().toLowerCase();
    if (term) {
      result = result.filter(s =>
        s.usuario?.area?.toLowerCase().includes(term) ||
        s.usuario?.nombre?.toLowerCase().includes(term)
      );
    }

    return result;
  }

  contarEstado(estado: FiltroEstado): number {
    if (estado === 'todos') return this.soportes.length;
    if (estado === 'pendiente') return this.soportes.filter(s => s.resolvio === null || s.resolvio === undefined).length;
    if (estado === 'si') return this.soportes.filter(s => s.resolvio === true).length;
    return this.soportes.filter(s => s.resolvio === false).length;
  }

  // ─── Carga de datos ──────────────────────────────────────────────────────────

  loadSoportes(): void {
    this.loading = true;
    this.soportesService.getAll().subscribe({
      next: (data) => { this.soportes = data; this.loading = false; },
      error: () => { this.error = 'Error al cargar los soportes'; this.loading = false; },
    });
  }

  // ─── Nueva solicitud ─────────────────────────────────────────────────────────

  openNuevaSolicitud(): void {
    this.nuevaSolicitudForm.reset();
    this.imagenPreview = null;
    this.nuevaModalVisible = true;
    const modal = new bootstrap.Modal(document.getElementById('nuevaSolicitudModal'));
    modal.show();
    document.getElementById('nuevaSolicitudModal')!.addEventListener('hidden.bs.modal', () => {
      this.nuevaModalVisible = false;
    }, { once: true });
  }

  guardarNuevaSolicitud(): void {
    if (this.nuevaSolicitudForm.invalid) { this.nuevaSolicitudForm.markAllAsTouched(); return; }
    this.savingNew = true;
    const { motivo } = this.nuevaSolicitudForm.value;
    this.soportesService.create(motivo, this.imagenPreview).subscribe({
      next: () => {
        this.savingNew = false;
        this.imagenPreview = null;
        this.nuevaModalVisible = false;
        bootstrap.Modal.getInstance(document.getElementById('nuevaSolicitudModal'))?.hide();
        this.loadSoportes();
        this.showSuccess('Solicitud creada exitosamente');
      },
      error: (err) => { this.savingNew = false; this.error = err?.error?.message || 'Error al crear la solicitud'; },
    });
  }

  // ─── Imagen (drag, drop, paste) ──────────────────────────────────────────────

  @HostListener('document:paste', ['$event'])
  onDocumentPaste(event: ClipboardEvent): void {
    if (!this.nuevaModalVisible) return;
    const items = event.clipboardData?.items;
    if (!items) return;
    for (const item of Array.from(items)) {
      if (item.type.startsWith('image/')) {
        const file = item.getAsFile();
        if (file) { this.processImageFile(file); break; }
      }
    }
  }

  onDragOver(event: DragEvent): void {
    event.preventDefault();
    event.stopPropagation();
    (event.currentTarget as HTMLElement).classList.add('drag-over');
  }

  onDragLeave(event: DragEvent): void {
    (event.currentTarget as HTMLElement).classList.remove('drag-over');
  }

  onDrop(event: DragEvent): void {
    event.preventDefault();
    (event.currentTarget as HTMLElement).classList.remove('drag-over');
    const file = event.dataTransfer?.files[0];
    if (file && file.type.startsWith('image/')) this.processImageFile(file);
  }

  onFileInput(event: Event): void {
    const file = (event.target as HTMLInputElement).files?.[0];
    if (file) this.processImageFile(file);
  }

  private processImageFile(file: File): void {
    const reader = new FileReader();
    reader.onload = (e) => {
      const img = new Image();
      img.onload = () => {
        const canvas = document.createElement('canvas');
        const MAX_W = 1000;
        const scale = img.width > MAX_W ? MAX_W / img.width : 1;
        canvas.width = Math.round(img.width * scale);
        canvas.height = Math.round(img.height * scale);
        canvas.getContext('2d')!.drawImage(img, 0, 0, canvas.width, canvas.height);
        this.imagenPreview = canvas.toDataURL('image/jpeg', 0.78);
      };
      img.src = e.target!.result as string;
    };
    reader.readAsDataURL(file);
  }

  removeImagen(): void { this.imagenPreview = null; }

  openImagenViewer(imagen: string): void {
    this.imagenViewer = imagen;
    const modal = new bootstrap.Modal(document.getElementById('imagenViewerModal'));
    modal.show();
  }

  // ─── Seguimiento ─────────────────────────────────────────────────────────────

  openSeguimiento(soporte: Soporte): void {
    this.seguimientoError = '';
    this.selectedSoporte = soporte;
    let dateVal = '', timeVal = '';
    if (soporte.fechaRespuesta) {
      const d = new Date(soporte.fechaRespuesta);
      const p = (n: number) => n.toString().padStart(2, '0');
      dateVal = `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}`;
      timeVal = `${p(d.getHours())}:${p(d.getMinutes())}`;
    }
    this.seguimientoForm.patchValue({
      fechaDate: dateVal,
      fechaTime: timeVal,
      resolvio: soporte.resolvio === true ? 'true' : soporte.resolvio === false ? 'false' : '',
      observaciones: soporte.observaciones || '',
    });
    const modal = new bootstrap.Modal(document.getElementById('seguimientoModal'));
    modal.show();
  }

  setFechaAhora(): void {
    const now = new Date();
    const p = (n: number) => n.toString().padStart(2, '0');
    this.seguimientoForm.patchValue({
      fechaDate: `${now.getFullYear()}-${p(now.getMonth()+1)}-${p(now.getDate())}`,
      fechaTime: `${p(now.getHours())}:${p(now.getMinutes())}`,
    });
  }

  guardarSeguimiento(): void {
    if (!this.selectedSoporte) return;

    const val = this.seguimientoForm.value;
    this.seguimientoError = '';

    // Validación: si se asigna estado (SI o NO) la fecha es obligatoria
    if ((val.resolvio === 'true' || val.resolvio === 'false') && !val.fechaDate) {
      this.seguimientoError = 'La fecha de respuesta es obligatoria cuando se asigna un estado.';
      return;
    }

    // Validación: si el estado es NO las observaciones son obligatorias
    if (val.resolvio === 'false' && !val.observaciones?.trim()) {
      this.seguimientoError = 'Las observaciones son obligatorias cuando el estado es NO.';
      return;
    }

    this.savingSeguimiento = true;
    const payload: any = { observaciones: val.observaciones?.trim() || null };
    if (val.fechaDate) {
      const time = val.fechaTime || '00:00';
      payload.fechaRespuesta = new Date(`${val.fechaDate}T${time}`).toISOString();
    }
    if (val.resolvio !== '' && val.resolvio !== null) payload.resolvio = val.resolvio === 'true';

    this.soportesService.update(this.selectedSoporte.id, payload).subscribe({
      next: () => {
        this.savingSeguimiento = false;
        bootstrap.Modal.getInstance(document.getElementById('seguimientoModal'))?.hide();
        this.loadSoportes();
        this.showSuccess('Seguimiento guardado correctamente');
      },
      error: (err) => { this.savingSeguimiento = false; this.error = err?.error?.message || 'Error al guardar seguimiento'; },
    });
  }

  // ─── Eliminar ────────────────────────────────────────────────────────────────

  eliminarSoporte(soporte: Soporte): void {
    if (!confirm(`¿Eliminar la solicitud #${soporte.id}?`)) return;
    this.soportesService.delete(soporte.id).subscribe({
      next: () => { this.loadSoportes(); this.showSuccess('Solicitud eliminada'); },
      error: (err) => { this.error = err?.error?.message || 'Error al eliminar'; },
    });
  }

  // ─── Cambio de contraseña ────────────────────────────────────────────────────

  openCambioClave(): void {
    this.cambioClaveForm.reset();
    this.claveError = '';
    this.claveSuccess = '';
    const modal = new bootstrap.Modal(document.getElementById('cambioClaveModal'));
    modal.show();
  }

  guardarCambioClave(): void {
    if (this.cambioClaveForm.invalid) { this.cambioClaveForm.markAllAsTouched(); return; }
    const { password, confirmPassword } = this.cambioClaveForm.value;
    if (password !== confirmPassword) { this.claveError = 'Las contraseñas no coinciden'; return; }
    this.savingClave = true;
    this.claveError = '';
    this.authService.changePassword(password, confirmPassword).subscribe({
      next: () => { this.savingClave = false; this.claveSuccess = 'Contraseña cambiada exitosamente'; this.cambioClaveForm.reset(); },
      error: (err) => { this.savingClave = false; this.claveError = err?.error?.message || 'Error al cambiar la contraseña'; },
    });
  }

  // ─── Export Excel ────────────────────────────────────────────────────────────

  openExportModal(): void {
    this.exportForm.reset();
    const modal = new bootstrap.Modal(document.getElementById('exportModal'));
    modal.show();
  }

  exportarExcel(): void {
    if (this.exportForm.invalid) { this.exportForm.markAllAsTouched(); return; }
    this.exporting = true;
    const { desde, hasta } = this.exportForm.value;
    this.soportesService.exportExcel(desde, hasta).subscribe({
      next: (blob) => {
        this.exporting = false;
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url; a.download = `soportes_${desde}_${hasta}.xlsx`; a.click();
        window.URL.revokeObjectURL(url);
        bootstrap.Modal.getInstance(document.getElementById('exportModal'))?.hide();
      },
      error: () => { this.exporting = false; this.error = 'Error al exportar el archivo'; },
    });
  }

  // ─── Helpers ─────────────────────────────────────────────────────────────────

  logout(): void { this.authService.logout(); }

  formatDate(dateStr: string | null | undefined): string {
    if (!dateStr) return '—';
    return new Date(dateStr).toLocaleString('es-CO', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' });
  }

  private showSuccess(msg: string): void {
    this.successMsg = msg;
    setTimeout(() => (this.successMsg = ''), 4000);
  }
}
