<!-- ═══ CONTENIDO ════════════════════════════════════════════════════════════ -->
<div class="container-fluid px-4 py-4">

  <!-- Alertas -->
  <div class="alert alert-success alert-dismissible py-2" *ngIf="successMsg">
    <i class="bi bi-check-circle me-1"></i>{{ successMsg }}
    <button type="button" class="btn-close py-2" (click)="successMsg=''"></button>
  </div>
  <div class="alert alert-danger alert-dismissible py-2" *ngIf="error">
    <i class="bi bi-exclamation-circle me-1"></i>{{ error }}
    <button type="button" class="btn-close py-2" (click)="error=''"></button>
  </div>

  <div class="card">

    <!-- ── Filtros + Búsqueda ────────────────────────────────────────────── -->
    <div class="card-header">
      <div class="d-flex align-items-center justify-content-between flex-wrap gap-3">

        <!-- Radio buttons de estado -->
        <div class="d-flex align-items-center gap-2 flex-wrap">
          <span class="fw-semibold text-muted small me-1">Filtrar:</span>

          <div class="filtro-radio-group">
            <input type="radio" id="f-todos" name="filtro" [(ngModel)]="filtroEstado" value="todos" class="btn-check">
            <label for="f-todos" class="btn btn-sm filtro-btn filtro-todos">
              Todos <span class="filtro-count">{{ contarEstado('todos') }}</span>
            </label>

            <input type="radio" id="f-pendiente" name="filtro" [(ngModel)]="filtroEstado" value="pendiente" class="btn-check">
            <label for="f-pendiente" class="btn btn-sm filtro-btn filtro-pendiente">
              Pendiente <span class="filtro-count">{{ contarEstado('pendiente') }}</span>
            </label>

            <input type="radio" id="f-si" name="filtro" [(ngModel)]="filtroEstado" value="si" class="btn-check">
            <label for="f-si" class="btn btn-sm filtro-btn filtro-si">
              SI <span class="filtro-count">{{ contarEstado('si') }}</span>
            </label>

            <input type="radio" id="f-no" name="filtro" [(ngModel)]="filtroEstado" value="no" class="btn-check">
            <label for="f-no" class="btn btn-sm filtro-btn filtro-no">
              NO <span class="filtro-count">{{ contarEstado('no') }}</span>
            </label>
          </div>
        </div>

        <!-- Búsqueda (admin y soporte) -->
        <div class="d-flex align-items-center gap-2" *ngIf="isAdmin || isSoporte">
          <div class="input-group input-group-sm" style="width: 260px;">
            <span class="input-group-text bg-white">
              <i class="bi bi-search text-muted"></i>
            </span>
            <input
              type="text"
              class="form-control"
              placeholder="Buscar por área o usuario..."
              [(ngModel)]="searchTerm"
            />
            <span class="input-group-text">
              <span class="badge" [class.bg-primary]="isAdmin" [class.bg-warning]="isSoporte" [class.text-dark]="isSoporte">
                {{ isAdmin ? 'Admin' : 'Soporte' }}
              </span>
            </span>
          </div>
          <button *ngIf="searchTerm" class="btn btn-sm btn-outline-secondary" (click)="searchTerm=''">
            <i class="bi bi-x"></i>
          </button>
        </div>

      </div>
    </div>

    <!-- Loading -->
    <div class="text-center py-5" *ngIf="loading">
      <div class="spinner-border text-primary" role="status"></div>
      <p class="mt-2 text-muted">Cargando solicitudes...</p>
    </div>

    <!-- Empty state -->
    <div class="text-center py-5" *ngIf="!loading && filteredSoportes.length === 0">
      <i class="bi bi-inbox" style="font-size: 3rem; color:#94a3b8;"></i>
      <p class="mt-2 text-muted">
        {{ soportes.length === 0 ? 'No hay solicitudes de soporte' : 'No hay resultados para el filtro seleccionado' }}
      </p>
      <button *ngIf="!isSoporte && soportes.length === 0" class="btn btn-primary btn-sm" (click)="openNuevaSolicitud()">
        <i class="bi bi-plus-lg me-1"></i>Crear primera solicitud
      </button>
    </div>

    <!-- ── Tabla ──────────────────────────────────────────────────────────── -->
    <div class="table-responsive tabla-soportes" *ngIf="!loading && filteredSoportes.length > 0">
      <table class="table table-hover table-sm mb-0">
        <thead>
          <tr>
            <th class="col-id">#</th>
            <th class="col-fecha">Fecha Solicitud</th>
            <th class="col-motivo">Motivo / Descripción</th>
            <th class="col-img" title="Imagen">IMG</th>
            <th *ngIf="isAdmin || isSoporte" class="col-area">Área</th>
            <th *ngIf="isAdmin || isSoporte" class="col-quien">Solicitante</th>
            <th *ngIf="isAdmin || isSoporte" class="col-tel">Teléfono</th>
            <th class="col-fecha">Fecha Respuesta</th>
            <th class="col-estado">Resolvió</th>
            <th class="col-obs">Observaciones</th>
            <th class="col-acciones th-sticky-right text-center">Acciones</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let s of filteredSoportes">
            <td class="col-id text-muted fw-semibold">{{ s.id }}</td>
            <td class="col-fecha small text-nowrap">{{ formatDate(s.fechaSolicitud) }}</td>
            <td class="col-motivo">
              <span class="cell-truncate" [title]="s.motivo">{{ s.motivo }}</span>
            </td>
            <td class="col-img text-center">
              <button *ngIf="s.imagen" class="btn btn-link p-0" title="Ver imagen"
                (click)="openImagenViewer(s.imagen!)">
                <i class="bi bi-image text-primary fs-5"></i>
              </button>
              <span *ngIf="!s.imagen" class="text-muted">—</span>
            </td>
            <td *ngIf="isAdmin || isSoporte" class="col-area small">{{ s.usuario.area || '—' }}</td>
            <td *ngIf="isAdmin || isSoporte" class="col-quien small">
              <span class="cell-truncate" [title]="s.usuario.nombre">{{ s.usuario.nombre }}</span>
            </td>
            <td *ngIf="isAdmin || isSoporte" class="col-tel small text-nowrap">
              <a *ngIf="s.usuario.telefono" [href]="'tel:'+s.usuario.telefono" class="text-decoration-none">
                <i class="bi bi-telephone-fill text-success me-1"></i>{{ s.usuario.telefono }}
              </a>
              <span *ngIf="!s.usuario.telefono" class="text-muted">—</span>
            </td>
            <td class="col-fecha small text-nowrap">{{ formatDate(s.fechaRespuesta) }}</td>
            <td class="col-estado">
              <span *ngIf="s.resolvio === true"  class="badge-si">SI</span>
              <span *ngIf="s.resolvio === false" class="badge-no">NO</span>
              <span *ngIf="s.resolvio === null || s.resolvio === undefined" class="badge-pendiente">Pdte.</span>
            </td>
            <td class="col-obs">
              <span class="cell-truncate text-muted small" [title]="s.observaciones || ''">
                {{ s.observaciones || '—' }}
              </span>
            </td>
            <!-- ACCIONES — sticky derecha -->
            <td class="col-acciones td-sticky-right text-center text-nowrap">
              <button *ngIf="canSeguimiento(s)"
                class="btn btn-outline-primary btn-sm me-1"
                title="Editar seguimiento"
                (click)="openSeguimiento(s)">
                <i class="bi bi-pencil-square"></i>
              </button>
              <button *ngIf="canDelete(s)"
                class="btn btn-outline-danger btn-sm"
                title="Eliminar"
                (click)="eliminarSoporte(s)">
                <i class="bi bi-trash"></i>
              </button>
              <span *ngIf="!canSeguimiento(s) && !canDelete(s)" class="text-muted small">—</span>
            </td>
          </tr>
        </tbody>
      </table>
    </div>

  </div><!-- /card -->
</div>

<!-- ═══ MODAL: Nueva Solicitud ═══════════════════════════════════════════════ -->
<div class="modal fade" id="nuevaSolicitudModal" tabindex="-1">
  <div class="modal-dialog modal-lg">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title"><i class="bi bi-plus-circle me-2"></i>Nueva Solicitud de Soporte</h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <form [formGroup]="nuevaSolicitudForm">
          <div class="mb-3">
            <label class="form-label fw-semibold">
              Motivo / Descripción <span class="text-danger">*</span>
            </label>
            <textarea
              class="form-control"
              formControlName="motivo"
              rows="4"
              placeholder="Describa detalladamente el motivo de la solicitud..."
            ></textarea>
            <div class="text-danger small mt-1"
              *ngIf="nuevaSolicitudForm.get('motivo')?.touched && nuevaSolicitudForm.get('motivo')?.invalid">
              El motivo es requerido (mínimo 5 caracteres)
            </div>
          </div>

          <!-- Zona de imagen -->
          <div class="mb-2">
            <label class="form-label fw-semibold">
              <i class="bi bi-image me-1"></i>Imagen adjunta (pantallazo)
              <span class="text-muted fw-normal small ms-1">— opcional</span>
            </label>

            <!-- Preview -->
            <div *ngIf="imagenPreview" class="mb-2 position-relative d-inline-block">
              <img [src]="imagenPreview" class="img-thumbnail" style="max-height:220px; max-width:100%;" />
              <button type="button" class="btn btn-danger btn-sm position-absolute top-0 end-0 m-1"
                (click)="removeImagen()" title="Quitar imagen">
                <i class="bi bi-x-lg"></i>
              </button>
            </div>

            <!-- Drop zone -->
            <div
              *ngIf="!imagenPreview"
              class="drop-zone"
              (dragover)="onDragOver($event)"
              (dragleave)="onDragLeave($event)"
              (drop)="onDrop($event)"
            >
              <i class="bi bi-cloud-arrow-up drop-zone-icon"></i>
              <p class="mb-1 fw-semibold">Arrastra una imagen aquí</p>
              <p class="text-muted small mb-2">o pega con <kbd>Ctrl+V</kbd> en cualquier lugar del modal</p>
              <label class="btn btn-outline-primary btn-sm">
                <i class="bi bi-folder2-open me-1"></i>Seleccionar archivo
                <input type="file" accept="image/*" class="d-none" (change)="onFileInput($event)">
              </label>
            </div>
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button>
        <button type="button" class="btn btn-primary" (click)="guardarNuevaSolicitud()" [disabled]="savingNew">
          <span *ngIf="savingNew" class="spinner-border spinner-border-sm me-1"></span>
          <i class="bi bi-save me-1" *ngIf="!savingNew"></i>
          {{ savingNew ? 'Guardando...' : 'Grabar Solicitud' }}
        </button>
      </div>
    </div>
  </div>
</div>

<!-- ═══ MODAL: Ver imagen ════════════════════════════════════════════════════ -->
<div class="modal fade" id="imagenViewerModal" tabindex="-1">
  <div class="modal-dialog modal-xl modal-dialog-centered">
    <div class="modal-content">
      <div class="modal-header py-2">
        <h6 class="modal-title"><i class="bi bi-image me-2"></i>Imagen adjunta</h6>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body text-center p-2">
        <img *ngIf="imagenViewer" [src]="imagenViewer" class="img-fluid rounded" style="max-height:80vh;" />
      </div>
    </div>
  </div>
</div>

<!-- ═══ MODAL: Seguimiento ═══════════════════════════════════════════════════ -->
<div class="modal fade" id="seguimientoModal" tabindex="-1">
  <div class="modal-dialog">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title">
          <i class="bi bi-clipboard2-check me-2"></i>Seguimiento
          <small *ngIf="selectedSoporte" class="ms-1 opacity-75">#{{ selectedSoporte.id }}</small>
        </h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <!-- Motivo solo lectura -->
        <div *ngIf="selectedSoporte" class="mb-3">
          <label class="form-label fw-semibold text-muted small">Motivo de la solicitud</label>
          <p class="border rounded p-2 bg-light mb-0 small lh-base">{{ selectedSoporte.motivo }}</p>
        </div>

        <form [formGroup]="seguimientoForm">
          <!-- Fecha + Hora separados + botón Ahora -->
          <div class="mb-3">
            <label class="form-label fw-semibold">Fecha y hora de respuesta</label>
            <div class="d-flex align-items-center gap-2 flex-wrap">
              <input type="date" class="form-control" formControlName="fechaDate"
                style="max-width:160px;" />
              <input type="time" class="form-control" formControlName="fechaTime"
                style="max-width:120px;" />
              <button type="button" class="btn btn-outline-secondary btn-sm text-nowrap"
                (click)="setFechaAhora()" title="Cargar fecha y hora actuales">
                <i class="bi bi-clock me-1"></i>Ahora
              </button>
            </div>
            <div class="form-text">Usa <strong>Ahora</strong> para llenar automáticamente con la fecha y hora del momento.</div>
          </div>

          <!-- Resolvió: radio buttons visuales -->
          <div class="mb-3">
            <label class="form-label fw-semibold">¿Resolvió el problema?</label>
            <div class="d-flex gap-3 mt-1">
              <div class="form-check">
                <input class="form-check-input" type="radio" formControlName="resolvio"
                  value="true" id="rSi">
                <label class="form-check-label fw-semibold text-success" for="rSi">
                  <i class="bi bi-check-circle-fill me-1"></i>SI
                </label>
              </div>
              <div class="form-check">
                <input class="form-check-input" type="radio" formControlName="resolvio"
                  value="false" id="rNo">
                <label class="form-check-label fw-semibold text-danger" for="rNo">
                  <i class="bi bi-x-circle-fill me-1"></i>NO
                </label>
              </div>
              <div class="form-check">
                <input class="form-check-input" type="radio" formControlName="resolvio"
                  value="" id="rPdte">
                <label class="form-check-label text-muted" for="rPdte">
                  <i class="bi bi-hourglass-split me-1"></i>Pendiente
                </label>
              </div>
            </div>
          </div>

          <!-- Observaciones -->
          <div class="mb-1">
            <label class="form-label fw-semibold">
              Observaciones
              <span class="text-danger"
                *ngIf="seguimientoForm.get('resolvio')?.value === 'false'"> *&nbsp;<small class="fw-normal">obligatorio cuando el estado es NO</small></span>
            </label>
            <textarea class="form-control" formControlName="observaciones" rows="4"
              placeholder="Ingrese las observaciones del seguimiento..."></textarea>
          </div>

          <!-- Alerta de validación -->
          <div class="alert alert-danger py-2 small mt-3 mb-0" *ngIf="seguimientoError">
            <i class="bi bi-exclamation-triangle-fill me-1"></i>{{ seguimientoError }}
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button>
        <button type="button" class="btn btn-primary" (click)="guardarSeguimiento()" [disabled]="savingSeguimiento">
          <span *ngIf="savingSeguimiento" class="spinner-border spinner-border-sm me-1"></span>
          <i class="bi bi-check-lg me-1" *ngIf="!savingSeguimiento"></i>
          {{ savingSeguimiento ? 'Guardando...' : 'Guardar Seguimiento' }}
        </button>
      </div>
    </div>
  </div>
</div>

<!-- ═══ MODAL: Cambio de Contraseña ══════════════════════════════════════════ -->
<div class="modal fade" id="cambioClaveModal" tabindex="-1">
  <div class="modal-dialog modal-sm">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title"><i class="bi bi-key me-2"></i>Cambiar Contraseña</h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <div class="alert alert-danger py-2 small" *ngIf="claveError">
          <i class="bi bi-exclamation-circle me-1"></i>{{ claveError }}
        </div>
        <div class="alert alert-success py-2 small" *ngIf="claveSuccess">
          <i class="bi bi-check-circle me-1"></i>{{ claveSuccess }}
        </div>
        <form [formGroup]="cambioClaveForm">
          <div class="mb-3">
            <label class="form-label fw-semibold">Nueva Contraseña</label>
            <input type="password" class="form-control" formControlName="password" placeholder="Mínimo 6 caracteres" />
            <div class="text-danger small mt-1"
              *ngIf="cambioClaveForm.get('password')?.touched && cambioClaveForm.get('password')?.invalid">
              Mínimo 6 caracteres
            </div>
          </div>
          <div class="mb-2">
            <label class="form-label fw-semibold">Repetir Contraseña</label>
            <input type="password" class="form-control" formControlName="confirmPassword" placeholder="Repita la contraseña" />
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary btn-sm" data-bs-dismiss="modal">Cancelar</button>
        <button type="button" class="btn btn-primary btn-sm" (click)="guardarCambioClave()" [disabled]="savingClave">
          <span *ngIf="savingClave" class="spinner-border spinner-border-sm me-1"></span>
          {{ savingClave ? 'Guardando...' : 'Cambiar' }}
        </button>
      </div>
    </div>
  </div>
</div>

<!-- ═══ MODAL: Exportar Excel ════════════════════════════════════════════════ -->
<div class="modal fade" id="exportModal" tabindex="-1">
  <div class="modal-dialog modal-sm">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title"><i class="bi bi-file-earmark-excel me-2"></i>Exportar a Excel</h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <form [formGroup]="exportForm">
          <div class="mb-3">
            <label class="form-label fw-semibold">Fecha Desde</label>
            <input type="date" class="form-control" formControlName="desde" />
            <div class="text-danger small mt-1"
              *ngIf="exportForm.get('desde')?.touched && exportForm.get('desde')?.invalid">Requerido</div>
          </div>
          <div class="mb-2">
            <label class="form-label fw-semibold">Fecha Hasta</label>
            <input type="date" class="form-control" formControlName="hasta" />
            <div class="text-danger small mt-1"
              *ngIf="exportForm.get('hasta')?.touched && exportForm.get('hasta')?.invalid">Requerido</div>
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary btn-sm" data-bs-dismiss="modal">Cancelar</button>
        <button type="button" class="btn btn-success btn-sm" (click)="exportarExcel()" [disabled]="exporting">
          <span *ngIf="exporting" class="spinner-border spinner-border-sm me-1"></span>
          <i class="bi bi-download me-1" *ngIf="!exporting"></i>
          {{ exporting ? 'Exportando...' : 'Descargar' }}
        </button>
      </div>
    </div>
  </div>
</div>
